import com.comsol.model.*;import com.comsol.model.util.*;import java.io.*;import java.util.*;
public class ReactiveEquationView{
 public static void main(String[] a){try{ModelUtil.initStandalone(false);ModelUtil.showProgress(false);Model m=ModelUtil.load("EqView",a[0]);PrintWriter p=new PrintWriter(a[1],"UTF-8");for(String ph:new String[]{"fp","tcs"}){for(String key:new String[]{"Expression","Weak","Constraint"}){p.println("ROOT|"+ph+"|"+key);for(String[] row:m.physics(ph).featureInfo("info").getInfoTable(key))p.println(Arrays.toString(row));}for(String tag:m.physics(ph).feature().tags())for(String key:new String[]{"Expression","Weak","Constraint"}){p.println("FEATURE|"+ph+"/"+tag+"|"+key);try{for(String[] row:m.physics(ph).feature(tag).featureInfo("info").getInfoTable(key))p.println(Arrays.toString(row));}catch(Throwable e){p.println("ERROR|"+e.getMessage());}p.flush();}}p.close();System.out.println("EQUATION_VIEW_EXPORTED");System.exit(0);}catch(Throwable e){e.printStackTrace(System.out);System.exit(1);}}
}
